'use strict';const cases=['queen','hawk'];function setup(c,s,variant){s.phase='MAIN_PHASE';s.turnNumber=3;s.activePlayerId='P1';s.pendingEffect=null;for(const p of s.playerOrder)for(const z of['hand','field','food','territory','discard'])s.player(p)[z]=[];s.player('P1').availableCost=0;function put(id,z,p='P1'){const d=c.getCardDefinition(id),x=new c.CardInstance({instanceId:s.nextInstanceId(),cardId:id,ownerId:p,controllerId:p,zone:z,baseHp:d.baseHp,currentHp:d.baseHp});s.player(p)[z.toLowerCase()].push(x);return x;}put(variant==='queen'?'set7_001':'set7_002','FIELD');if(variant==='queen'){const t=put('kabutomushi','FIELD','P2');c.addStatModifier(s,t,{stat:'HP',amount:5000});put('set2_007','FOOD');put('set2_007','FOOD').faceDown=true;put('set7_001','FOOD');}else{put('set4_021','FIELD','P2').currentHp=100;put('namitentou','FIELD','P2');put('set2_007','FOOD');}}
